\begin{tikzpicture}[line join=round, line width=1.6pt, font=\fontsize{16.5}{19.8}\selectfont]
  % Named coordinates
  \coordinate (A) at (1.9096,1.9096);
  \coordinate (B) at (-3.7890,-1.8900);
  \coordinate (C) at (3.7890,-1.8900);
  \coordinate (D) at (1.9096,-1.8900);
  \coordinate (O) at (0.3783,0.2274);  % circle centre
  \def\R{2.1614}                        % circle radius

  % Thin light circle, visible arcs only
  \begin{scope}[line width=0.8pt, draw=gray!60]
    % image 42..112 deg -> TikZ -112..-42
    \draw ($(O)+(-112:\R)$) arc[start angle=-112, end angle=-42, radius=\R];
    % image 311..355 deg -> TikZ 5..49
    \draw ($(O)+(5:\R)$) arc[start angle=5, end angle=49, radius=\R];
  \end{scope}

  % Triangle sides
  \draw (A) -- (B);
  \draw (A) -- (C);
  \draw (B) -- (C);
  % Altitude
  \draw (A) -- (D);

  % Right-angle mark at D (inside the angle between DA and DC)
  \draw (D) ++(-0.38,0) -- ++(0,0.38) -- ++(0.38,0);

  % Labels
  \node[above] at (A) {$A$};
  \node[below left] at (B) {$B$};
  \node[below right] at (C) {$C$};
  \node[below] at (D) {$D$};
\end{tikzpicture}
\end{document}

